 async void RunChecks(){if(OS.GetCmdlineUserArgs().Contains("--mid-terrain")){await RunMidTerrainChecks();return;}if(NpcWorkEnabled){await RunNpcWorkChecks();return;}if(RegionalWorkEnabled){await RunRegionalWorkChecks();return;}if(NoticeEnabled){await RunNoticeChecks();return;}if(ReviewEnabled){await RunReviewChecks();return;}if(IncomingEnabled){await RunIncomingChecks();return;}if(CouncilEnabled){await RunCouncilChecks();return;}if(EntryEnabled){await RunEntryChecks();return;}if(LoopEnabled){await RunLoopChecks();return;}try{System.IO.Directory.CreateDirectory(Output);if(Mode.EndsWith("restore")){for(int i=0;i<Stages.Length;i++){Load(Case+"-s"+i);Check(Pose()==System.IO.File.ReadAllText(Output+"/"+Case+"-s"+i+"-pose.json"),"restored world/tiles/camera/models "+i);await Capture("restored-s"+i);Click("resume");Check(!S.Paused,"restore can resume through actual UI button");Advance(Final);await Capture("continued-s"+i);}}else{Arrange();Check(S.DiagnosticSnapshot().Region!.Commands.All(c=>c.Result is "applied" or "in-transit"),"request applied or physically in transit");foreach(var i in Enumerable.Range(0,Stages.Length)){Advance(Stages[i]);Refresh();Save(Case+"-s"+i);System.IO.File.WriteAllText(Output+"/"+Case+"-s"+i+"-pose.json",Pose());await Capture("s"+i);}Advance(Final);await Capture("final");var w=S.DiagnosticSnapshot();ContractValidation.Validate(w);Check(ground.Resident<=25,"bounded resident chunks");if(w.Region!.Active&&span<=240){var probe=follow?Current():center;var hit=Pick(camera.UnprojectPosition(P(probe)));Check(hit!=null&&RegionalGround.Distance(hit,probe)<20,"real ray picking agrees with Core height and world coordinates "+hit+" / "+probe);}
 if(Case=="assets"){Check(ground.Skin=="skin:swap-demo"&&ground.PackedAssetCount>0&&ground.Notices.Length==0,"actual external rock scenes loaded within static footprint contract");Check(ground.RoadTexturePreserved,"explicit road resource texture is not overwritten by procedural improvement");}
 if(Case=="coverage"){var oldCenter=center;bool oldFollow=follow;follow=false;var before=ContractJson.CanonicalHash(S.DiagnosticSnapshot());foreach(var node in NationalRoutes.Nodes){center=ContinuousWorld.Origin(node.Id);Refresh();await ToSignal(GetTree(),SceneTree.SignalName.ProcessFrame);await ToSignal(RenderingServer.Singleton,RenderingServer.SignalName.FramePostDraw);Check(ground.Resident==25,"national streamed coverage "+node.Id);if(node.Id is "shuri" or "katsuyama" or "odawara")await Capture("coverage-"+node.Id);}center=oldCenter;follow=oldFollow;Refresh();Check(before==ContractJson.CanonicalHash(S.DiagnosticSnapshot()),"108-site GPU coverage leaves world unchanged");}
if(Case is "order" or "refuse"){Check(w.Region!.Deliveries.Length>=2,"physical order and return report across chunks");Check(w.Region.Commands.Single().Result==(Case=="refuse"?"refused":"applied"),"officer decision respected");Check(RegionalBattle.Status(w,w.Region.Commands.Single(),ContractFixture.Officer)==w.Region.Commands.Single().Result,"report actually reached player");}else if(Case is "combat" or "rout"){Check(w.Region!.Losses.Length>0,"contact causes simultaneous recorded losses");if(Case=="rout")Check(w.Region.Units.Any(u=>u.Phase=="routed"),"low morale causes retreat");}else if(Case!="travel"){Check(w.Region!.Units.Where(u=>u.Commander==ContractFixture.Officer).All(u=>u.Position==u.Goal),"detachments arrived across chunk boundary");}else{Check(!TravelWorld.Active(w),"national road journey arrived");Click("site");Check(S.DiagnosticSnapshot().Atlas!.Anchor=="fork","arrived region can be deployed without resetting time");span=200;Refresh();await Capture("arrival");}
 var hash=ContractJson.CanonicalHash(S.DiagnosticSnapshot());bool q=ground.Improved;Click("quality");await Capture("quality-alternate");Click("quality");await Capture("quality-back");Check(hash==ContractJson.CanonicalHash(S.DiagnosticSnapshot())&&ground.Improved==q,"visual quality cannot change world");var savedCenter=center;float savedSpan=span;bool savedFollow=follow;Click("nation");await Capture("nation");Check(ground.Resident==0,"national LOD evicts all detail chunks");var nationalBounds=new Rect2(Vector2.Zero,new Vector2(viewport.Size.X,viewport.Size.Y));Check(shores.SelectMany(s=>s.Ring).All(g=>{var p=JapanGeography.Project(g);return nationalBounds.HasPoint(camera.UnprojectPosition(Flat(new(p.EastMm,p.NorthMm))));}),"entire published coastline fits national viewport");center=savedCenter;span=savedSpan;follow=savedFollow;Refresh();Check(hash==ContractJson.CanonicalHash(S.DiagnosticSnapshot()),"zoom cannot change simulation");await Capture("zoom-back");Check(ground.Resident<=25,"detail reload remains bounded");foreach(var view in RegionalBattle.View(S.DiagnosticSnapshot(),ContractFixture.Officer).Where(v=>v.Live&&actors.ContainsKey(v.Unit)))Check(Math.Abs(actors[view.Unit].Position.Y-view.Height/1000f)<.002f,"model foot uses Core height "+view.Unit.Value);}
 System.IO.File.WriteAllText(Output+"/"+Case+"-"+(Mode.EndsWith("restore")?"restore":"check")+"-checks.json",System.Text.Json.JsonSerializer.Serialize(new{Checks=checks,Resident=ground.Resident,ground.Created,ground.Evicted,Triangles=ground.Triangles,Skin=ground.Skin,PackedAssets=ground.PackedAssetCount,Fallbacks=ground.Notices,RefreshMs=timings.ToArray(),ViewportRect=new[]{surface.GlobalPosition.X,surface.GlobalPosition.Y,surface.Size.X,surface.Size.Y}}));GD.Print("CONTINUOUS_CHECK_PASSED "+Case);GetTree().Quit();}catch(Exception e){GD.PrintErr(e);GetTree().Quit(1);}}
 void BeginVideo(){System.IO.Directory.CreateDirectory(Output);if(LoopEnabled){videoReady=true;return;}Click("nation");videoReady=true;}
 void Video(){if(LoopEnabled){LoopVideo();return;}int f=frame++;if(f<96){span=Mathf.Exp(Mathf.Lerp(Mathf.Log(2800000),Mathf.Log(30000),f/95f));center=Current();follow=true;}if(f==96)span=240;if(f>=96&&f<144)span=Mathf.Lerp(240,160,(f-96)/47f);if(f==144)Click("move");if(f>=144&&f<288)Advance(Math.Max(S.Seconds,(long)((f-144)*1.3)));if(f==288)Save("movie");if(f==312){Load("movie");Click("resume");}if(f==336){Issue(RegionalAction.Retreat);span=200;}if(f>=336&&f<432)Advance(S.Seconds+2);if(f==432)Click("order");if(f>=432&&f<576)Advance(S.Seconds+1);if(f==576){span=160;follow=false;center=ContinuousWorld.Point(S.DiagnosticSnapshot().Atlas!.Anchor,-120000,-120000);ground.Improved=false;}if(f==600)ground.Improved=true;notice.Text=f<96?"① 全国と現在地は同じ座標":f<144?"② 地域から詳細地形へ。最大25区画":f<288?"③ 80m区画の境界を越えて移動":f<336?"④ 途中保存・復旧。位置と背景を維持":f<432?"⑤ 同じ世界時間で帰還":f<576?"⑥ 別働隊への物理伝令と返報":"⑦ 背景表現を替えても移動判定は共通";Refresh();if(f>=623){GD.Print("CONTINUOUS_VIDEO_PASSED 624");GetTree().Quit();}}
 public override void _Process(double delta){if(videoReady){try{Video();}catch(Exception e){GD.PrintErr(e);GetTree().Quit(1);}return;}if(Mode!=""||!automatic||S.Paused)return;fraction+=Math.Min(delta,.25)*speed;long n=(long)fraction;if(n>0){Advance(S.Seconds+n);fraction-=n;}Refresh();}
